import{_ as t,o as e,c as o,aa as s}from"./chunks/framework.BAs_AphD.js";const r="/buildary-help-preview/academy/img/vykresy-mapa/02.webp",n="/buildary-help-preview/media/cs/tickets/vykres.png",l="/buildary-help-preview/media/cs/tickets/mapa.png",c=JSON.parse('{"title":"Výkresy a mapa","description":"","frontmatter":{"title":"Výkresy a mapa","wiki":"cs:tickets:task_drawings"},"headers":[],"relativePath":"tickets/task_drawings.md","filePath":"tickets/task_drawings.md","lastUpdated":1794209661000}'),k={name:"tickets/task_drawings.md"};function i(p,a,v,d,u,m){return e(),o("div",null,[...a[0]||(a[0]=[s('<h1 id="vykresy-a-mapa" tabindex="-1">Výkresy a mapa <a class="header-anchor" href="#vykresy-a-mapa" aria-label="Permalink to &quot;Výkresy a mapa&quot;">​</a></h1><p>Stránka <strong>Výkresy a Mapa</strong> ukazuje úkoly jako značky na výkresech stavby a v mapě. Hodí se při obchůzce stavby nebo při kontrole, co se na kterém místě řeší. Dvojklikem do výkresu nebo mapy tu také rovnou založíte nový úkol.</p><p>Krok za krokem: <a href="/buildary-help-preview/akademie/vykresy-mapa">Zobrazit úkoly na výkrese nebo v mapě</a> v Akademii.</p><p>Stránku otevřete v levém panelu volbou <strong>Výkresy a Mapa</strong>, nebo na Dashboardu tlačítkem <strong>Výkresy</strong> či <strong>Mapa</strong>. Výkresy a mapa jsou na samostatných záložkách, číslo u záložky udává počet úkolů umístěných na výkresech, resp. v mapě.</p><p>Na výkresech se ukážou jen úkoly, které mají ve výkresu značku, a v mapě jen úkoly s polohou. Značku a polohu zadáte při zakládání nebo úpravě úkolu – viz <a href="/buildary-help-preview/tickets/task_new#umisteni-na-vykresu-a-v-mape">Zadat úkol</a>.</p><h2 id="vykresy" tabindex="-1">Výkresy <a class="header-anchor" href="#vykresy" aria-label="Permalink to &quot;Výkresy&quot;">​</a></h2><figure class="shot" style="--w:760px;"><img src="'+r+'" alt="Záložka Výkresy s filtrem podle části stavby a náhledem výkresu s počtem úkolů" loading="lazy"></figure><p>Na záložce <strong>Výkresy</strong> jsou náhledy všech výkresů stavby. U každého výkresu vidíte, kolik úkolů je na něm vyznačeno. Výběrem <strong>Filtrovat podle části stavby</strong> zobrazíte jen výkresy jedné části.</p><p>Výkresy nahrává k částem stavby administrátor – viz <a href="/buildary-help-preview/diary/projectparts">Části stavby a výkresy</a>.</p><h3 id="ukoly-na-vykresu" tabindex="-1">Úkoly na výkresu <a class="header-anchor" href="#ukoly-na-vykresu" aria-label="Permalink to &quot;Úkoly na výkresu&quot;">​</a></h3><p>Kliknutím na náhled otevřete výkres se značkami úkolů. Barva značky odpovídá stavu úkolu. Zpět na přehled výkresů se vrátíte tlačítkem <strong>Zpět na seznam výkresů</strong>.</p><figure class="shot" style="--w:760px;"><img src="'+n+'" alt="Výkres se značkami úkolů, rozbalenými filtry Stav, Kategorie, Vztah k úkolu a Aktuálnost úkolu a informacemi o úkolu s tlačítkem Přejdi na detail úkolu" loading="lazy"></figure><p>Značky na výkresu omezíte filtry nad výkresem:</p><table tabindex="0"><thead><tr><th>Filtr</th><th>Možnosti</th></tr></thead><tbody><tr><td><strong>Stav</strong></td><td><strong>Koncept</strong> až <strong>Schváleno</strong> – všechny stavy úkolu</td></tr><tr><td><strong>Kategorie</strong></td><td>kategorie úkolů stavby</td></tr><tr><td><strong>Vztah k úkolu</strong></td><td>například <strong>Mnou řešené úkoly</strong> nebo <strong>Mnou schvalované</strong></td></tr><tr><td><strong>Aktuálnost úkolu</strong></td><td>například <strong>Zpožděné</strong> nebo <strong>Neukončené</strong></td></tr><tr><td><strong>Část stavby</strong></td><td>úkoly jedné části</td></tr></tbody></table><p>Hodnoty filtrů jsou stejné jako v Seznamu úkolů – viz <a href="/buildary-help-preview/tickets/task_grid">Seznam úkolů a filtry</a>.</p><p>Když najedete myší na značku, zobrazí se předmět, popis, priorita, stav a Řešitelé úkolu. Tlačítkem <strong>Přejdi na detail úkolu</strong> úkol otevřete.</p><div class="tip custom-block"><p class="custom-block-title">Nový úkol z výkresu</p><p>Dvojklikem na kterékoli místo ve výkresu otevřete formulář <strong>Nový úkol</strong> se značkou v tomto místě.</p></div><h2 id="mapa" tabindex="-1">Mapa <a class="header-anchor" href="#mapa" aria-label="Permalink to &quot;Mapa&quot;">​</a></h2><p>Na záložce <strong>Mapa</strong> se mapa otevře tak, aby byly vidět všechny úkoly s polohou. Kliknutím na značku zobrazíte předmět, popis, prioritu, stav a Řešitele úkolu a tlačítko <strong>Přejdi na detail úkolu</strong>.</p><figure class="shot" style="--w:760px;"><img src="'+l+'" alt="Letecká mapa se značkami úkolů a otevřenými informacemi o úkolu" loading="lazy"></figure><ul><li>Ikonou vrstev vpravo dole přepnete mezi základní a leteckou mapou.</li><li>Tlačítky <strong>+</strong> a <strong>−</strong> vlevo nahoře mapu přiblížíte a oddálíte, ikonou vpravo nahoře ji zobrazíte na celou obrazovku.</li></ul><div class="tip custom-block"><p class="custom-block-title">Nový úkol z mapy</p><p>Dvojklikem na kterékoli místo v mapě otevřete formulář <strong>Nový úkol</strong> s polohou v tomto místě.</p></div><p>Výkresy a mapu s úkoly máte i v mobilní aplikaci – viz <a href="/buildary-help-preview/tickets/m_task_grid#ukoly-na-vykresu-a-v-mape">Úkoly v mobilu</a>.</p>',23)])])}const g=t(k,[["render",i]]);export{c as __pageData,g as default};
